<template><span :class="['status', tone]">{{ label }}</span></template>
<script setup lang="ts">import {computed} from 'vue';const props=defineProps<{value?:string|boolean}>();const label=computed(()=>props.value===true?'Active':props.value===false?'Inactive':String(props.value??'—').replace('_',' '));const tone=computed(()=>{const v=String(props.value??'').toLowerCase();if(['paid','active','completed'].includes(v)||props.value===true)return 'status-success';if(['overdue','cancelled','voided','inactive'].includes(v)||props.value===false)return 'status-danger';if(['partial','issued','draft'].includes(v))return 'status-warning';return 'status-neutral'})</script>
